import os
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _bounding_box_to_list(bounding_regions: Any) -> List[Dict[str, Any]]:
    regions_out: List[Dict[str, Any]] = []
    if not bounding_regions:
        return regions_out

    for region in bounding_regions:
        polygon = []
        if getattr(region, "polygon", None):
            polygon = [{"x": p.x, "y": p.y} for p in region.polygon]
        regions_out.append(
            {
                "page_number": getattr(region, "page_number", None),
                "polygon": polygon,
            }
        )
    return regions_out


def _serialize_words(words: Any) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    if not words:
        return out
    for w in words:
        out.append(
            {
                "content": getattr(w, "content", None),
                "confidence": getattr(w, "confidence", None),
                "polygon": [{"x": p.x, "y": p.y} for p in getattr(w, "polygon", [])] if getattr(w, "polygon", None) else [],
            }
        )
    return out


def _serialize_table(table: Any) -> Dict[str, Any]:
    cells: List[Dict[str, Any]] = []
    for cell in getattr(table, "cells", []) or []:
        cells.append(
            {
                "kind": getattr(cell, "kind", None),
                "row_index": getattr(cell, "row_index", None),
                "column_index": getattr(cell, "column_index", None),
                "row_span": getattr(cell, "row_span", None),
                "column_span": getattr(cell, "column_span", None),
                "content": getattr(cell, "content", None),
                "bounding_regions": _bounding_box_to_list(getattr(cell, "bounding_regions", None)),
                "confidence": getattr(cell, "confidence", None),
            }
        )
    return {
        "row_count": getattr(table, "row_count", None),
        "column_count": getattr(table, "column_count", None),
        "cells": cells,
        "bounding_regions": _bounding_box_to_list(getattr(table, "bounding_regions", None)),
    }


def extract_layout_elements(
    document_url: Optional[str] = None,
    file_path: Optional[str] = None,
    model_id: str = "prebuilt-layout",
) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    if document_url:
        poller = client.begin_analyze_document(model_id=model_id, analyze_request={"urlSource": document_url})
    elif file_path:
        with open(file_path, "rb") as f:
            poller = client.begin_analyze_document(model_id=model_id, body=f)
    else:
        raise ValueError("Either document_url or file_path must be provided.")

    result = poller.result()

    pages: List[Dict[str, Any]] = []
    for page in getattr(result, "pages", []) or []:
        lines: List[Dict[str, Any]] = []
        for line in getattr(page, "lines", []) or []:
            lines.append(
                {
                    "content": getattr(line, "content", None),
                    "polygon": [{"x": p.x, "y": p.y} for p in getattr(line, "polygon", [])] if getattr(line, "polygon", None) else [],
                    "spans": [
                        {"offset": s.offset, "length": s.length} for s in getattr(line, "spans", []) or []
                    ],
                }
            )

        words: List[Dict[str, Any]] = _serialize_words(getattr(page, "words", None))
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
                "lines": lines,
                "words": words,
            }
        )

    paragraphs: List[Dict[str, Any]] = []
    for para in getattr(result, "paragraphs", []) or []:
        paragraphs.append(
            {
                "content": getattr(para, "content", None),
                "role": getattr(para, "role", None),
                "spans": [{"offset": s.offset, "length": s.length} for s in getattr(para, "spans", []) or []],
                "bounding_regions": _bounding_box_to_list(getattr(para, "bounding_regions", None)),
            }
        )

    tables: List[Dict[str, Any]] = [_serialize_table(t) for t in getattr(result, "tables", []) or []]

    return {
        "model_id": model_id,
        "content": getattr(result, "content", None),
        "pages": pages,
        "paragraphs": paragraphs,
        "tables": tables,
    }
